    private fun icon(name: String, path: String, viewport: Float): ImageVector =
        ImageVector.Builder(
            name = name,
            defaultWidth = 24.dp,
            defaultHeight = 24.dp,
            viewportWidth = viewport,
            viewportHeight = viewport
        ).addPath(pathData = addPathNodes(path), fill = SolidColor(Color.Black)).build()
